-- =============================================
-- Author:        FRANCO LARA / Codex
-- Create date:   25/08/2026
-- Description:   Reemplaza los maestros desde cero, omite GeneraDiferenciaPorAnalisis, elimina Ejercicio e importa desde SIAC legacy la empresa 01.
-- =============================================

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY

    BEGIN TRAN;

    IF OBJECT_ID(N'dbo.CON_PlanCuentaMaestro', N'U') IS NULL
       OR OBJECT_ID(N'dbo.CON_CuentaDestinoReglaMaestro', N'U') IS NULL
       OR OBJECT_ID(N'dbo.CON_CuentaDestinoReglaDetalleMaestro', N'U') IS NULL
       OR OBJECT_ID(N'dbo.CON_CuentaDestinoRegla', N'U') IS NULL
    BEGIN
        RAISERROR(N'Debe crear las tablas maestras contables antes de ejecutar esta importacion.', 16, 1);
    END;

    IF COL_LENGTH(N'dbo.CON_CuentaDestinoReglaMaestro', N'Ejercicio') IS NOT NULL
    BEGIN
        EXEC sys.sp_executesql N'
            ;WITH ReglasDuplicadas AS
            (
                SELECT
                    regla.IdCuentaDestinoReglaMaestro,
                    ROW_NUMBER() OVER
                    (
                        PARTITION BY regla.CodigoCuentaOrigen
                        ORDER BY regla.Ejercicio DESC, regla.IdCuentaDestinoReglaMaestro DESC
                    ) AS NumeroFila
                FROM dbo.CON_CuentaDestinoReglaMaestro AS regla
            )
            DELETE detalle
            FROM dbo.CON_CuentaDestinoReglaDetalleMaestro AS detalle
            INNER JOIN ReglasDuplicadas AS duplicada
                ON duplicada.IdCuentaDestinoReglaMaestro = detalle.IdCuentaDestinoReglaMaestro
            WHERE duplicada.NumeroFila > 1;

            ;WITH ReglasDuplicadas AS
            (
                SELECT
                    regla.IdCuentaDestinoReglaMaestro,
                    ROW_NUMBER() OVER
                    (
                        PARTITION BY regla.CodigoCuentaOrigen
                        ORDER BY regla.Ejercicio DESC, regla.IdCuentaDestinoReglaMaestro DESC
                    ) AS NumeroFila
                FROM dbo.CON_CuentaDestinoReglaMaestro AS regla
            )
            DELETE regla
            FROM dbo.CON_CuentaDestinoReglaMaestro AS regla
            INNER JOIN ReglasDuplicadas AS duplicada
                ON duplicada.IdCuentaDestinoReglaMaestro = regla.IdCuentaDestinoReglaMaestro
            WHERE duplicada.NumeroFila > 1;';

        IF EXISTS
        (
            SELECT 1
            FROM sys.key_constraints AS restriccion
            WHERE restriccion.name = N'UQ_CON_CuentaDestinoReglaMaestro'
              AND restriccion.parent_object_id = OBJECT_ID(N'dbo.CON_CuentaDestinoReglaMaestro')
        )
        BEGIN
            ALTER TABLE dbo.CON_CuentaDestinoReglaMaestro
                DROP CONSTRAINT UQ_CON_CuentaDestinoReglaMaestro;
        END;

        EXEC sys.sp_executesql N'
            ALTER TABLE dbo.CON_CuentaDestinoReglaMaestro DROP COLUMN Ejercicio;';
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM sys.key_constraints AS restriccion
        WHERE restriccion.name = N'UQ_CON_CuentaDestinoReglaMaestro'
          AND restriccion.parent_object_id = OBJECT_ID(N'dbo.CON_CuentaDestinoReglaMaestro')
    )
    BEGIN
        ALTER TABLE dbo.CON_CuentaDestinoReglaMaestro
            ADD CONSTRAINT UQ_CON_CuentaDestinoReglaMaestro UNIQUE (CodigoCuentaOrigen);
    END;

    IF COL_LENGTH(N'dbo.CON_CuentaDestinoRegla', N'Ejercicio') IS NOT NULL
    BEGIN
        EXEC sys.sp_executesql N'
            ALTER TABLE dbo.CON_CuentaDestinoRegla DROP COLUMN Ejercicio;';
    END;

    CREATE TABLE #PlanCuentaLegacy
    (
        CodigoCuenta VARCHAR(20) NOT NULL PRIMARY KEY,
        CodigoCuentaPadre VARCHAR(20) NULL,
        NombreCuenta NVARCHAR(200) NOT NULL,
        NivelCuenta TINYINT NOT NULL,
        ColBalance CHAR(1) NOT NULL,
        IdMoneda VARCHAR(3) NOT NULL,
        TipoCambio CHAR(1) NOT NULL,
        AceptaMovimiento BIT NOT NULL,
        GeneraDiferenciaPorAnalisis BIT NOT NULL,
        RequiereCentroCosto BIT NOT NULL,
        Orden INT NOT NULL
    );

