    DELETE FROM dbo.CON_CuentaDestinoReglaDetalleMaestro;
    DELETE FROM dbo.CON_CuentaDestinoReglaMaestro;
    DELETE FROM dbo.CON_PlanCuentaMaestro;

    DBCC CHECKIDENT (N'dbo.CON_CuentaDestinoReglaDetalleMaestro', RESEED, -1) WITH NO_INFOMSGS;
    DBCC CHECKIDENT (N'dbo.CON_CuentaDestinoReglaMaestro', RESEED, -1) WITH NO_INFOMSGS;
    DBCC CHECKIDENT (N'dbo.CON_PlanCuentaMaestro', RESEED, -1) WITH NO_INFOMSGS;

    SET IDENTITY_INSERT dbo.CON_PlanCuentaMaestro ON;

    INSERT INTO dbo.CON_PlanCuentaMaestro
    (
        IdPlanCuentaMaestro, CodigoCuenta, CodigoCuentaPadre, NombreCuenta, NivelCuenta,
        ColBalance, IdMoneda, TipoCambio, AceptaMovimiento,
        RequiereCentroCosto, Estado, Orden, UsuarioRegistro
    )
    SELECT
        CONVERT(INT, ROW_NUMBER() OVER (ORDER BY fuente.Orden, fuente.CodigoCuenta) - 1),
        fuente.CodigoCuenta,
        fuente.CodigoCuentaPadre,
        fuente.NombreCuenta,
        fuente.NivelCuenta,
        fuente.ColBalance,
        fuente.IdMoneda,
        fuente.TipoCambio,
        fuente.AceptaMovimiento,
        fuente.RequiereCentroCosto,
        1,
        fuente.Orden,
        N'importacion-legacy-01'
    FROM #PlanCuentaLegacy AS fuente;

    SET IDENTITY_INSERT dbo.CON_PlanCuentaMaestro OFF;

    CREATE TABLE #CuentaDestinoLegacy
    (
        CodigoCuentaOrigen VARCHAR(20) NOT NULL PRIMARY KEY,
        CodigoCuentaDestinoCargo VARCHAR(20) NOT NULL,
        CodigoCuentaDestinoAbono VARCHAR(20) NOT NULL,
        Porcentaje DECIMAL(7,4) NOT NULL
    );

