    ('97611009', '67611001', '79111002', 100.0000);

    IF EXISTS
    (
        SELECT 1
        FROM #CuentaDestinoLegacy AS regla
        CROSS APPLY
        (
            VALUES
                (regla.CodigoCuentaOrigen),
                (regla.CodigoCuentaDestinoCargo),
                (regla.CodigoCuentaDestinoAbono)
        ) AS codigo (CodigoCuenta)
        LEFT JOIN dbo.CON_PlanCuentaMaestro AS cuenta
            ON cuenta.CodigoCuenta = codigo.CodigoCuenta
           AND cuenta.Estado = 1
           AND cuenta.AceptaMovimiento = 1
        WHERE cuenta.IdPlanCuentaMaestro IS NULL
    )
    BEGIN
        RAISERROR(N'Existen cuentas destino que no pertenecen al plan maestro operativo importado.', 16, 1);
    END;

    SET IDENTITY_INSERT dbo.CON_CuentaDestinoReglaMaestro ON;

    INSERT INTO dbo.CON_CuentaDestinoReglaMaestro
    (
        IdCuentaDestinoReglaMaestro, CodigoCuentaOrigen, Activo,
        Observacion, UsuarioRegistro
    )
    SELECT
        CONVERT(INT, ROW_NUMBER() OVER (ORDER BY fuente.CodigoCuentaOrigen) - 1),
        fuente.CodigoCuentaOrigen,
        1,
        N'Importado de SIAC legacy, empresa 01.',
        N'importacion-legacy-01'
    FROM #CuentaDestinoLegacy AS fuente;

    SET IDENTITY_INSERT dbo.CON_CuentaDestinoReglaMaestro OFF;

    SET IDENTITY_INSERT dbo.CON_CuentaDestinoReglaDetalleMaestro ON;

    INSERT INTO dbo.CON_CuentaDestinoReglaDetalleMaestro
    (
        IdCuentaDestinoReglaDetalleMaestro, IdCuentaDestinoReglaMaestro, Orden,
        CodigoCuentaDestinoCargo, CodigoCuentaDestinoAbono, Porcentaje,
        Activo, UsuarioRegistro
    )
    SELECT
        CONVERT(INT, ROW_NUMBER() OVER (ORDER BY regla.CodigoCuentaOrigen) - 1),
        cabecera.IdCuentaDestinoReglaMaestro,
        CAST(1 AS SMALLINT),
        regla.CodigoCuentaDestinoCargo,
        regla.CodigoCuentaDestinoAbono,
        regla.Porcentaje,
        1,
        N'importacion-legacy-01'
    FROM #CuentaDestinoLegacy AS regla
    INNER JOIN dbo.CON_CuentaDestinoReglaMaestro AS cabecera
        ON cabecera.CodigoCuentaOrigen = regla.CodigoCuentaOrigen;

    SET IDENTITY_INSERT dbo.CON_CuentaDestinoReglaDetalleMaestro OFF;

    DROP TABLE #CuentaDestinoLegacy;
    DROP TABLE #PlanCuentaLegacy;

    COMMIT;

    SELECT CAST(2173 AS INT) AS CuentasPlanProcesadas,
           CAST(574 AS INT) AS ReglasDestinoProcesadas,
           CAST(311 AS INT) AS ReglasDestinoExcluidas;

END TRY
BEGIN CATCH

    IF OBJECT_ID(N'dbo.CON_CuentaDestinoReglaDetalleMaestro', N'U') IS NOT NULL
        EXEC sys.sp_executesql N'SET IDENTITY_INSERT dbo.CON_CuentaDestinoReglaDetalleMaestro OFF;';

    IF OBJECT_ID(N'dbo.CON_CuentaDestinoReglaMaestro', N'U') IS NOT NULL
        EXEC sys.sp_executesql N'SET IDENTITY_INSERT dbo.CON_CuentaDestinoReglaMaestro OFF;';

    IF OBJECT_ID(N'dbo.CON_PlanCuentaMaestro', N'U') IS NOT NULL
        EXEC sys.sp_executesql N'SET IDENTITY_INSERT dbo.CON_PlanCuentaMaestro OFF;';

    IF @@TRANCOUNT > 0
    BEGIN
        ROLLBACK;
    END;

    DECLARE @ErrorMessage NVARCHAR(4000)
    DECLARE @ErrorSeverity INT
    DECLARE @ErrorState INT

    SELECT
        @ErrorMessage = ERROR_MESSAGE(),
        @ErrorSeverity = ERROR_SEVERITY(),
        @ErrorState = ERROR_STATE()

    RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState)

END CATCH
